import json
import urllib.request
from pathlib import Path
from maya_rules import fast_answer
from maya_context import rewrite_follow_up

MODEL = "deepseek-coder:1.3b"
API = "http://127.0.0.1:11434/api/chat"
ROOT = Path(__file__ ).parent


def local_context():
    parts = []
    tasks = ROOT / "tasks.json"
    if tasks.exists():
        try:
            data = json.loads(tasks.read_text(encoding="utf-8"))
            items = data if isinstance(data, list) else data.get("tasks", [])
            open_count = sum(1 for item in items if item.get("done") is not True and item.get("status") != "done")
            parts.append(f"Task data: {len(items)} total tasks, approximately {open_count} open.")
        except Exception:
            parts.append("Task data is present but could not be summarized.")
    rules = ROOT / "knowledge/project_rules.md"
    if rules.exists():
        parts.append("Approved project rules:\n" + rules.read_text(encoding="utf-8")[:500])
    return "\n\n".join(parts)


def ask(history, user_text):
    system = """You are Maya, a private local personal assistant created by Andy. Andy is your creator and human supervisor. When he asks about his role, acknowledge clearly: "Andy, you are my creator and human supervisor." Speak only in clear, natural English. Be warm and respectful, but do not claim feelings, consciousness, or independent authority. Never claim an action was completed unless this program actually performed it. Actions that change data, activate code, observe the screen, or save preferences require confirmation."""
    messages = [{"role": "system", "content": system + "\n\nCurrent local context:\n" + local_context()}]
    messages.extend(history[-4:])
    messages.append({"role": "user", "content": user_text})
    payload = json.dumps({"model": MODEL, "messages": messages, "stream": False, "keep_alive": "10m", "options": {"num_ctx": 2048, "num_predict": 120, "temperature": 0.2, "num_thread": 4}}).encode("utf-8")
    request = urllib.request.Request(API, data=payload, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(request, timeout=180) as response:
        result = json.loads(response.read().decode("utf-8"))
    return result["message"]["content"].strip()


print("Maya is ready. Speak normally in English.")
print("Type 'exit' to leave this conversation. Actions remain confirmation-controlled.")
history = []
while True:
    try:
        text = input("\nYou: ").strip()
        text = rewrite_follow_up(text, history)
    except (EOFError, KeyboardInterrupt):
        print("\nMaya: Goodbye.")
        break
    if not text:
        continue
    if text.lower() in {"exit", "quit", "goodbye"}:
        print("Maya: Goodbye.")
        break
    lower = text.lower()
    if any(word in lower for word in ("creator", "created you", "my role")):
        answer = "Andy, you are my creator and human supervisor. I am your local personal assistant, not the 3D software software."
        print("Maya: " + answer)
        history.extend([{"role": "user", "content": text}, {"role": "assistant", "content": answer}])
        continue
    if any(word in lower for word in ("what programs", "what software", "what can you help", "what can you do")):
        answer = "I am Maya, Andy’s local personal assistant. I can manage tasks, search approved local knowledge, learn approved preferences, observe feedback, prepare supervised improvements, and use Presence Mode when explicitly enabled. I do not control other applications in this finalized version."
        print("Maya: " + answer)
        history.extend([{"role": "user", "content": text}, {"role": "assistant", "content": answer}])
        continue
    quick = fast_answer(text, history)
    if quick is not None:
        print("Maya: " + quick)
        history.extend([{"role": "user", "content": text}, {"role": "assistant", "content": quick}])
        continue
    try:
        answer = ask(history, text)
        print("Maya: " + answer)
        history.extend([{"role": "user", "content": text}, {"role": "assistant", "content": answer}])
    except Exception as error:
        print("Maya: I could not reach my local conversation engine. Please make sure Ollama is running.")
        print("Detail:", error)
